# validate_dataset.py
# Analyzes and validates the .npy datasets generated by generate_datasets.py.
#
# Checks (per position):
#   - All expected files exist (data_time_domain, data_frequency_domain, labels, groups)
#   - Shape consistency: N is identical across all four files
#   - Window dimensions match expected array size (1020 for CHEST, 450 for LEFT/RIGHT)
#   - Channel count is exactly 8
#   - No NaN or Inf values in data arrays
#   - Label values are only 0 or 1
#   - Group IDs are integers in [1, 15]
#   - Class balance (fall vs non-fall) per position and per group
#   - Per-group sample count (every individual present)
#
# Usage:
#   python validate_dataset.py [--output <dataset_root>] [--positions chest left right]

import argparse
import os
import sys

import numpy as np

EXPECTED_CHANNELS   = 8
EXPECTED_OUTPUT_SIZE = 460
EXPECTED_FREQ_SIZE  = {k: v // 2 for k, v in EXPECTED_OUTPUT_SIZE.items()}
VALID_LABELS        = {0, 1}
VALID_GROUPS        = set(range(1, 16))

# ── CLI ───────────────────────────────────────────────────────────────────────
parser = argparse.ArgumentParser(description="Validate single-sensor .npy datasets")
parser.add_argument(
    "--output", type=str,
    default=os.path.join(os.path.dirname(os.path.abspath(__file__)), "..","..","dataset"),
    help="Root dataset directory (contains chest/, left/, right/ subdirs)",
)
parser.add_argument(
    "--positions", type=str, nargs="+", default=["chest", "left", "right"],
    choices=["chest", "left", "right"],
    help="Which positions to validate (default: all three)",
)
args = parser.parse_args()

dataset_root = os.path.abspath(args.output)

# ── Helpers ───────────────────────────────────────────────────────────────────
PASS = "  [PASS]"
FAIL = "  [FAIL]"
WARN = "  [WARN]"

def ok(msg):   print(f"{PASS} {msg}")
def fail(msg): print(f"{FAIL} {msg}"); global _any_fail; _any_fail = True
def warn(msg): print(f"{WARN} {msg}")

_any_fail = False


def check_finite(arr, name):
    n_nan = int(np.isnan(arr).sum())
    n_inf = int(np.isinf(arr).sum())
    if n_nan > 0:
        fail(f"{name}: contains {n_nan} NaN values")
    if n_inf > 0:
        fail(f"{name}: contains {n_inf} Inf values")
    if n_nan == 0 and n_inf == 0:
        ok(f"{name}: no NaN / Inf")


# ── Main validation loop ──────────────────────────────────────────────────────
for position in args.positions:
    print(f"\n{'='*60}")
    print(f"  POSITION: {position.upper()}")
    print(f"{'='*60}")

    data_dir  = os.path.join(dataset_root, position, "data")
    label_dir = os.path.join(dataset_root, position, "labels")

    time_path   = os.path.join(data_dir,  "data_time_domain.npy")
    freq_path   = os.path.join(data_dir,  "data_frequency_domain.npy")
    label_path  = os.path.join(label_dir, "labels.npy")
    groups_path = os.path.join(label_dir, "groups.npy")

    # ── 1. File existence ──────────────────────────────────────────────────
    print("\n-- File existence --")

    file_exists = {
        "time": os.path.isfile(time_path),
        "freq": os.path.isfile(freq_path),
        "labels": os.path.isfile(label_path),
        "groups": os.path.isfile(groups_path),
    }
    for k, p in zip(file_exists.keys(), [time_path, freq_path, label_path, groups_path]):
        if file_exists[k]:
            ok(os.path.basename(p))
        else:
            fail(f"MISSING: {p}")

    # Only load arrays that exist
    time_arr = freq_arr = labels = groups = None
    if file_exists["time"]:
        time_arr = np.load(time_path)
    if file_exists["freq"]:
        freq_arr = np.load(freq_path)
    if file_exists["labels"]:
        labels = np.load(label_path)
    if file_exists["groups"]:
        groups = np.load(groups_path)

    # If labels or groups are missing, cannot continue with most checks
    if not (file_exists["labels"] and file_exists["groups"]):
        warn("labels.npy or groups.npy missing, skipping further checks for this position")
        continue

    # ── 2. Load arrays ────────────────────────────────────────────────────

    print(f"\n-- Shapes --")
    if time_arr is not None:
        print(f"  time  : {time_arr.shape}")
    else:
        print(f"  time  : [NOT LOADED]")
    if freq_arr is not None:
        print(f"  freq  : {freq_arr.shape}")
    else:
        print(f"  freq  : [NOT LOADED]")
    print(f"  labels: {labels.shape}")
    print(f"  groups: {groups.shape}")

    N = labels.shape[0]

    # ── 3. Shape consistency ──────────────────────────────────────────────

    print("\n-- Shape consistency --")
    for name, arr in [("time", time_arr), ("freq", freq_arr), ("groups", groups)]:
        if arr is not None:
            if arr.shape[0] == N:
                ok(f"{name}.shape[0] == {N}")
            else:
                fail(f"{name}.shape[0] = {arr.shape[0]}, expected {N} (from labels)")

    # ── 4. Window size ────────────────────────────────────────────────────

    print("\n-- Window dimensions --")
    exp_t = EXPECTED_OUTPUT_SIZE[position]
    exp_f = EXPECTED_FREQ_SIZE[position]

    if time_arr is not None:
        if time_arr.ndim == 3 and time_arr.shape[1] == exp_t:
            ok(f"time window size = {time_arr.shape[1]} (expected {exp_t})")
        else:
            fail(f"time window size = {time_arr.shape[1] if time_arr.ndim==3 else '?'} , expected {exp_t}")
    if freq_arr is not None:
        if freq_arr.ndim == 3 and freq_arr.shape[1] == exp_f:
            ok(f"freq window size = {freq_arr.shape[1]} (expected {exp_f})")
        else:
            fail(f"freq window size = {freq_arr.shape[1] if freq_arr.ndim==3 else '?'} , expected {exp_f}")

    # ── 5. Channel count ──────────────────────────────────────────────────

    print("\n-- Channel count --")
    for name, arr in [("time", time_arr), ("freq", freq_arr)]:
        if arr is not None:
            ch = arr.shape[2] if arr.ndim == 3 else "?"
            if ch == EXPECTED_CHANNELS:
                ok(f"{name} channels = {ch}")
            else:
                fail(f"{name} channels = {ch}, expected {EXPECTED_CHANNELS}")

    # ── 6. NaN / Inf ──────────────────────────────────────────────────────

    print("\n-- NaN / Inf checks --")
    if time_arr is not None:
        check_finite(time_arr, "time_domain")
    if freq_arr is not None:
        check_finite(freq_arr, "freq_domain")

    # ── 7. Label values ───────────────────────────────────────────────────

    print("\n-- Label values --")
    unique_labels = set(np.unique(labels).tolist())
    invalid_labels = unique_labels - VALID_LABELS
    if invalid_labels:
        fail(f"Unexpected label values: {invalid_labels}")
    else:
        ok(f"All label values in {VALID_LABELS}")

    # ── 8. Group IDs ──────────────────────────────────────────────────────

    print("\n-- Group IDs --")
    unique_groups = set(np.unique(groups).tolist())
    invalid_groups = unique_groups - VALID_GROUPS
    if invalid_groups:
        fail(f"Unexpected group IDs: {invalid_groups}")
    else:
        ok(f"All group IDs valid")

    missing_groups = VALID_GROUPS - unique_groups
    if missing_groups:
        warn(f"Groups absent from dataset: {sorted(missing_groups)}")
    else:
        ok(f"All 15 individuals present")

    # ── 9. Class balance ──────────────────────────────────────────────────

    print("\n-- Class balance --")
    n_fall    = int((labels == 1).sum())
    n_no_fall = int((labels == 0).sum())
    ratio = n_fall / N if N > 0 else 0
    print(f"  Total samples : {N}")
    print(f"  Non-fall (0)  : {n_no_fall}  ({100*(1-ratio):.1f}%)")
    print(f"  Fall     (1)  : {n_fall}  ({100*ratio:.1f}%)")
    if ratio < 0.05:
        warn("Fall class is under 5% — very imbalanced")
    elif ratio > 0.95:
        warn("Non-fall class is under 5% — very imbalanced")
    else:
        ok("Class balance looks reasonable")

    # ── 10. Per-group breakdown ───────────────────────────────────────────

    print("\n-- Per-group sample counts --")
    print(f"  {'ID':<6} {'total':>7} {'fall':>7} {'non-fall':>10} {'fall%':>7}")
    print(f"  {'-'*6} {'-'*7} {'-'*7} {'-'*10} {'-'*7}")
    for gid in sorted(unique_groups):
        mask = groups == gid
        g_total  = int(mask.sum())
        g_fall   = int(labels[mask].sum())
        g_nofall = g_total - g_fall
        g_ratio  = 100 * g_fall / g_total if g_total > 0 else 0
        flag = " <-- no falls!" if g_fall == 0 else (" <-- no ADLs!" if g_nofall == 0 else "")
        print(f"  ID{gid:<4} {g_total:>7} {g_fall:>7} {g_nofall:>10} {g_ratio:>6.1f}%{flag}")

print(f"\n{'='*60}")
if _any_fail:
    print("  RESULT: FAILED — see [FAIL] items above")
    sys.exit(1)
else:
    print("  RESULT: ALL CHECKS PASSED")
